// Element 18 — OrderProcessingStateView. Customer-facing, read-only: one append-only vertical timeline, oldest first.
// Never shows money, waybill, assignee, warehouse locations, issue kind, pick list, ETA or fractional progress.
// Leg states follow 03-parcel: parcelReady == collection requested, i.e. before L2 ("collected by the provider").
import { STORIES, esc, mount, button, page } from './_ui.js';

const step = (s) => `
  <li class="${s.status}">${esc(s.label)}${s.at ? `<span class="at">${esc(s.at)}</span>` : ''}${
    s.note ? `<div class="note">${esc(s.note)}</div>` : ''
  }</li>`;

const timeline = (title, steps) => `<h2>${esc(title)}</h2><ol class="timeline">${steps.map(step).join('')}</ol>`;

const kv = (k, v, note) =>
  `<div class="row"><span class="k">${esc(k)}</span><span>${esc(v)}${note ? `<div class="note">${esc(note)}</div>` : ''}</span></div>`;

const view = (d) => `
  <section class="card">
    <h1>Order ${esc(d.processingId)}</h1>
    ${d.hold ? '<div class="banner bad">Paused — this order is on hold. No detail and no issue kind is shown to the customer (Q-18-1).</div>' : ''}
    ${d.banner ? `<div class="banner${d.bannerBad ? ' bad' : ''}">${esc(d.banner)}</div>` : ''}
    <h2>What you ordered</h2>
    ${d.lines.map((l) => kv(l.productNumber, `${l.name} × ${l.quantity}`)).join('')}
    ${kv('Delivery target', d.delivery.value, d.delivery.note)}
    ${kv('Payment method', d.payment.value, d.payment.note)}
  </section>

  <aside class="card">
    ${timeline('Order', d.orderSteps)}
    ${timeline('Delivery', d.legs)}
    <p class="note">${esc(d.note)}</p>
    <div class="actions">
      ${button({ id: 'simulate-leg', label: d.simulate.label, primary: !d.simulate.disabled, go: d.simulate.target, disabled: d.simulate.disabled, reason: d.simulate.reason })}
    </div>
  </aside>`;

const render = (args) =>
  mount(
    document.createElement('div'),
    page({
      crumbs: '/ fulfillment / my orders / ' + args.processingId,
      actor: args.actor,
      access: args.access,
      currentStory: args.currentStory,
      body: view(args),
    }),
  );

export default { title: 'Fulfillment/Customer State', render };

const LEG = {
  L1: 'L1 · parcel registered',
  L2: 'L2 · collected by the provider',
  L3: 'L3 · assigned for pickup',
  L4: 'L4 · picked up',
  L5: 'L5 · in the sorting facility',
  L6: 'L6 · customer picked it up',
};

const leg = (code, status, at, note) => ({ label: LEG[code], status, at, note });

const base = {
  actor: 'Jan Kowalski',
  access: 'own order only — how a guest order reaches its own view is undecided (Q-18-2)',
  processingId: 'OP-2026-0001',
  lines: [{ productNumber: '75423', name: "LEGO Star Wars SMART Play X-Wing Czerwona Piątka Luke'a", quantity: 1 }],
  delivery: { value: 'PICKUP_POINT · point KRA01M', note: 'default: the pickup point arrives as an opaque id — no name or address exists in any source (R-01-1)' },
  payment: { value: 'not shown', note: 'default: no payment-method list exists, so nothing can be labelled (UND-21)' },
  note:
    'Append-only: a state once shown is never removed, replaced or moved backwards (03 RULE-4). Timestamps are when we ' +
    'received the event, not the carrier timestamp (Q-18-1 default). Freshness is poll-based, so this screen never implies live tracking (R-18-1).',
};

